import React, { useState } from "react";
import axios from "axios";
import { API } from "../config";

export default function Home() {
  const [vehicle, setVehicle] = useState("");
  const [challans, setChallans] = useState([]);

  const fetchChallans = async () => {
    try {
      const res = await axios.get(`${API}/challan/vehicle/${vehicle}`);
      setChallans(res.data);
    } catch (err) {
      alert("Error fetching challans");
    }
  };

  return (
    <div>
      <h2>Check Challan</h2>
      <input placeholder="Vehicle Number" value={vehicle} onChange={e => setVehicle(e.target.value)} />
      <button onClick={fetchChallans}>Search</button>

      {challans.length > 0 && (
        <table border="1" cellPadding="6">
          <thead>
            <tr>
              <th>#</th>
              <th>Vehicle</th>
              <th>Cause</th>
              <th>Fine</th>
              <th>Status</th>
              <th>Issue Date</th>
              <th>Due Date</th>
              <th>Address</th>
            </tr>
          </thead>
          <tbody>
            {challans.map((c, i) => (
              <tr key={i}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>{c.issueDate}</td>
                <td>{c.dueDate}</td>
                <td>{c.address}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
